import sys

def solution(data: str) -> str:
    t = int(data.splitlines()[0])
    output_lines = []
    idx = 1
    for _ in range(t):
        n, k = map(int, data.splitlines()[idx].split())
        idx += 1
        if n == 1:
            if k == 1:
                output_lines.append("1")
            else:
                output_lines.append("-1")
            continue
        # For n == 2, there are no good permutations except k == 1
        # For n >= 3, the good permutation is always 2 1 3 4 ... n, and only exists for k == 1
        if n == 2:
            if k == 1:
                output_lines.append("2 1")
            else:
                output_lines.append("-1")
            continue
        if k == 1:
            perm = [2, 1] + list(range(3, n + 1))
            output_lines.append(' '.join(map(str, perm)))
        else:
            output_lines.append("-1")
    return '\n'.join(output_lines)
